'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrmmda = require( '@stdlib/stats/incr/mmda' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving mean directional accuracy, ignoring `NaN` values.
*
* @param {PositiveInteger} W - window size
* @throws {TypeError} must provide a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmmda( 3 );
*
* var m = accumulator();
* // returns null
*
* m = accumulator( 2.0, 3.0 );
* // returns 1.0
*
* m = accumulator( 5.0, 2.0 );
* // returns 0.5
*
* m = accumulator( NaN, NaN );
* // returns 0.5
*
* m = accumulator( 3.0, 2.0 );
* // returns ~0.33
*
* m = accumulator( 4.0, NaN );
* // returns ~0.33
*
* m = accumulator( 4.0, 5.0 );
* // returns ~0.33
*
* m = accumulator();
* // returns ~0.33
*/
function incrnanmmda( W ) {
	var mmda = incrmmda( W );
	return accumulator;

	/**
	* If provided input values, the accumulator function returns an updated mean directional accuracy. If not provided input values or if either of the values provided is NaN, the accumulator function returns the current mean directional accuracy.
	*
	* @private
	* @param {number} [f] - forecast value
	* @param {number} [a] - actual value
	* @returns {(number|null)} mean directional accuracy or null
	*/
	function accumulator( f, a ) {
		if ( arguments.length === 0 || isnan( f ) || isnan( a ) ) {
			return mmda();
		}
		return mmda( f, a );
	}
}


// EXPORTS //

module.exports = incrnanmmda;
